INSERT INTO `item_unique` (`key`, `name`, `base_entry`, `item_level`, `required_level`, `description`, `creature_entry`, `chance`, `raised_item_level`, `raised_required_level`) VALUES
('hogger', 'Hogger''s Gnawbone', 1009, 14, 9, 'Still warm. Hogger was not done with it.', 448, 0.5, 63, 60),
('vancleef', 'VanCleef''s Ledger-Blade', 5540, 23, 18, 'Every debt Stormwind owes is carved into the blade.', 639, 1, 63, 60),
('mutanus', 'Mantle of the Waking Dream', 4314, 23, 18, 'Naralex dreams on; the mantle remembers what woke.', 3654, 1, 63, 60),
('arugal', 'Arugal''s Worgen-Bound Cloak', 2316, 24, 19, 'Stitched from the first pelt of the Moonrage.', 4275, 1, 63, 60),
('charlga', 'Thornweave Leggings of Charlga', 4830, 30, 25, 'Woven from the thorns that grew from her blood.', 4421, 1, 63, 60),
('morladim', 'Mor''Ladim''s Grave-Ring', 1116, 33, 28, 'He swore to return for her. The ring kept the promise.', 522, 0.5, 63, 60),
('thalnos', 'Thalnos''s Bloodstained Vestments', 1997, 36, 31, 'The stains are older than the Crusade.', 4543, 1, 63, 60),
('herod', 'Herod''s Crusading Pauldrons', 3765, 42, 37, 'Blades of the Scarlet champion, worn to the bone.', 3975, 1, 63, 60),
('theradras', 'Girdle of the Earthmother''s Grief', 8129, 51, 46, 'Theradras mourns, and the earth answers.', 12201, 1, 63, 60),
('eranikus', 'Nightmare-Touched Grips', 8260, 53, 48, 'The Emerald Dream is not what it was.', 5709, 1, 63, 60),
('rivendare', 'The Baron''s Deathcharger Blade', 15256, 62, 58, 'Rivendare''s last order: ride.', 10440, 1, 63, 60),
('taragaman', 'Hungerer''s Smoldering Grips', 6554, 17, 12, 'Taragaman ate the Burning Blade''s fear. His hands still smoke.', 11520, 1, 63, 60),
('akumai', 'Aku''mai''s Third Fang', 4446, 27, 22, 'Pulled from the hydra''s middle jaw. It still drips.', 4829, 1, 63, 60),
('bazil', 'Thredd''s Riot Cudgel', 13048, 27, 22, 'The Stockade riot started with this club and ended with it.', 1716, 1, 63, 60),
('thermaplugg', 'Thermaplugg''s Overclocked Boomstick', 7729, 32, 27, 'Mekgineer-grade. Safety catch removed for performance.', 7800, 1, 63, 60),
('doan', 'Doan''s Unbound Grimoire', 1992, 38, 33, 'The Scarlet Crusade burned every copy but this one.', 6487, 1, 63, 60),
('whitemane', 'Whitemane''s Vestments of the Second Rising', 1716, 42, 37, '"Arise, my champion!" Sometimes it works on the wearer, too.', 3977, 1, 63, 60),
('amnennar', 'Coldbringer''s Rimed Spaulders', 7718, 40, 35, 'Frost from the barrow-lich''s own phylactery.', 7358, 1, 63, 60),
('archaedas', 'Archaedas'' Titanwrought Bulwark', 18342, 45, 40, 'A stone keeper''s ward, cut from the vault door.', 2748, 1, 63, 60),
('ukorz', 'Sandscalp''s Sunscorched Cleaver', 9481, 49, 44, 'Zul''Farrak''s chief took heads for the sun. The sun never asked for them.', 7267, 1, 63, 60),
('thaurissan', 'Crown of the Fire Emperor', 12633, 60, 55, 'Thaurissan summoned Ragnaros. The crown remembers the heat.', 9019, 1, 63, 60),
('alzzin', 'Wildshaper''s Thornhide Tunic', 15059, 60, 55, 'Alzzin wore a dozen shapes. This is the one he died in.', 11492, 1, 63, 60),
('wyrmthalak', 'Wyrmthalak''s Dragonspine Halberd', 13148, 61, 56, 'Its haft is a black dragon''s spine. The dragon did not volunteer.', 9568, 1, 63, 60),
('tortheldrin', 'Tortheldrin''s Mana-Starved Grips', 18407, 62, 57, 'The prince fed on his own people''s mana. His gloves learned the trick.', 11486, 1, 63, 60),
('gandling', 'Gandling''s Detention Ledger', 18639, 62, 57, 'Every name in it was sent to a room. None came back.', 1853, 1, 63, 60),
('gordok', 'Gordok''s Crown-Breaker', 12796, 62, 57, 'Kill the king, become the king. This is how the last one did it.', 11501, 1, 63, 60),
('balnazzar', 'Balnazzar''s Cowl of Many Faces', 14140, 62, 57, 'He wore Grand Crusader Dathrohan''s face for years. No one noticed.', 10813, 1, 63, 60),
('drakkisath', 'Drakkisath''s Flamescale Warplate', 16730, 63, 58, 'Forged for the general of the Black Dragonflight. Rend never got one.', 10363, 1, 0, 0),
('jeklik', 'Jeklik''s Batwing Shroud', 22712, 68, 60, 'Her shriek is stitched into the hem.', 14517, 2, 0, 0),
('venoxis', 'Venoxis'' Serpentcoil Leggings', 16843, 68, 60, 'The high priest shed this skin on his way to becoming a snake.', 14507, 2, 0, 0),
('marli', 'Mar''li''s Silkfang', 19166, 68, 60, 'Spider venom on one edge, silk on the other.', 14510, 2, 0, 0),
('mandokir', 'Mandokir''s Headsman''s Blade', 18542, 68, 60, 'Ohgan carried the heads back. Mandokir kept count.', 11382, 2, 0, 0),
('thekal', 'Thekal''s Tigerclaw', 19896, 68, 60, 'The high priest got up twice. Make sure you finish it.', 14509, 2, 0, 0),
('arlokk', 'Arlokk''s Shadowprowl Treads', 16824, 68, 60, 'Panthers don''t walk. They wait closer.', 14515, 2, 0, 0),
('jindo', 'Jin''do''s Hexweave Mantle', 19370, 68, 60, 'Jin''do never cast the same hex twice. He just liked this one best.', 11380, 2, 0, 0),
('hakkar', 'Hakkar''s Blood-Siphon Band', 17110, 72, 60, 'The Soulflayer fed on blood. The band is still hungry.', 14834, 2, 0, 0),
('grilek', 'Gri''lek''s Iron Stride', 20039, 68, 60, 'Gri''lek of the Iron Blood never took a step back.', 15082, 2, 0, 0),
('hazzarah', 'Hazza''rah''s Dreamcatcher', 14557, 68, 60, 'Hazza''rah could make you see anything. This is what he wanted you to see.', 15083, 2, 0, 0),
('renataki', 'Renataki''s Vanishing Grips', 18823, 68, 60, 'You won''t see him. You''ll see these, briefly.', 15084, 2, 0, 0),
('wushoolay', 'Wushoolay''s Stormcaller Hauberk', 20380, 68, 60, 'Rain follows the wearer, and so does the lightning.', 15085, 2, 0, 0),
('gahzranka', 'Gahz''ranka''s Tidecaller Pendant', 17065, 68, 60, 'Fished up with a Mudskunk Lure. Seriously.', 15114, 2, 0, 0),
('lucifron', 'Lucifron''s Doomsayer Chain', 17109, 72, 60, 'Lucifron promised doom. He delivered it in this.', 12118, 2, 0, 0),
('magmadar', 'Magmadar''s Molten Gaze', 17069, 72, 60, 'Strung with core hound sinew. The panic is optional.', 11982, 2, 0, 0),
('gehennas', 'Gehennas'' Rain of Fire Gauntlets', 16860, 72, 60, 'Gehennas cursed healing. These just burn.', 12259, 2, 0, 0),
('garr', 'Garr''s Firesworn Bulwark', 17066, 72, 60, 'Garr''s firesworn exploded when they died. The shield learned to take it.', 12057, 2, 0, 0),
('geddon', 'Geddon''s Living Bomb', 18820, 72, 60, 'Hold it away from your friends. Then run.', 12056, 2, 0, 0),
('shazzrah', 'Shazzrah''s Blinkstep Slippers', 16803, 72, 60, 'Shazzrah blinked into melee range on purpose. Nobody knows why.', 12264, 2, 0, 0),
('sulfuron', 'Sulfuron''s Dark Mending Scepter', 17105, 72, 60, 'The Harbinger kept his priests alive long past their use.', 12098, 2, 0, 0),
('golemagg', 'Golemagg''s Magma-Forged Legplates', 22651, 72, 60, 'Core ragers guarded him. Now they guard you.', 11988, 2, 0, 0),
('ragnaros', 'Ragnaros'' Magmawrath Cleaver', 17104, 78, 60, 'BY FIRE BE PURGED, the blade reads, in letters that still glow.', 11502, 2, 0, 0),
('onyxia', 'Onyxia''s Wyrmhide Jerkin', 22661, 75, 60, 'The broodmother''s scales, worked by Lady Prestor''s own tailor.', 10184, 2, 0, 0),
('razorgore', 'Razorgore''s Broodkeeper Pauldrons', 16953, 76, 60, 'He guarded the eggs. He did not guard them well.', 12435, 2, 0, 0),
('vaelastrasz', 'Vaelastrasz''s Burning Adrenaline', 19339, 76, 60, 'Vael gave his strength freely. Then it burned him.', 13020, 2, 0, 0),
('lashlayer', 'Lashlayer''s Broodlord Blade', 19351, 76, 60, 'Pulled from the Broodlord''s hand before the blast wave.', 12017, 2, 0, 0),
('firemaw', 'Firemaw''s Flamebuffet Grips', 16940, 76, 60, 'Each buffet hit harder than the last. So does the wearer.', 11983, 2, 0, 0),
('ebonroc', 'Ebonroc''s Shadowtouched Bracers', 22663, 76, 60, 'Ebonroc healed on every hit. You may borrow the habit.', 14601, 2, 0, 0),
('flamegor', 'Flamegor''s Frenzied Band', 19397, 76, 60, 'Tranquilizing Shot was not enough. Neither is this ring.', 11981, 2, 0, 0),
('chromaggus', 'Chromaggus'' Five-Breath Mantle', 19386, 76, 60, 'Nefarian bred Chromaggus to breathe every color. The hide resists them all.', 14020, 2, 0, 0),
('nefarian', 'Nefarian''s Shadowflame Scepter', 19356, 83, 60, 'The son of Deathwing calls every class. This answers.', 11583, 2, 0, 0),
('kurinnaxx', 'Kurinnaxx''s Sandtrap Claw', 21673, 70, 60, 'Kurinnaxx''s wounds never close. Neither will theirs.', 15348, 2, 0, 0),
('rajaxx', 'Rajaxx''s Warlord Insignia', 17065, 70, 60, 'General Rajaxx ordered a thousand charges. Only the last one failed.', 15341, 2, 0, 0),
('moam', 'Moam''s Manaweave Leggings', 19165, 70, 60, 'Moam drained everything near him. This only drains him.', 15340, 2, 0, 0),
('buru', 'Buru''s Gorger Breastplate', 22196, 70, 60, 'Buru ate eggs. Now you eat damage.', 15370, 2, 0, 0),
('ayamiss', 'Ayamiss'' Stinger', 20599, 70, 60, 'Ayamiss hunted from the air. This brings it back to earth.', 15369, 2, 0, 0),
('ossirian', 'Ossirian''s Crystal-Bound Greatsword', 18542, 74, 60, 'The Unscarred feared only the crystals. This blade is made of them.', 15339, 2, 0, 0),
('skeram', 'Skeram''s Prophetic Eye', 21625, 79, 60, 'The Prophet saw three futures. In all of them, you take this.', 15263, 2, 0, 0),
('bugtrio', 'Leggings of the Royal Brood', 22701, 79, 60, 'Vem, Kri and Yauj shared everything. Mostly their loot.', 15544, 2, 0, 0),
('sartura', 'Sartura''s Whirling Cleaver', 21242, 79, 60, 'The Battleguard spun until nothing stood. Keep spinning.', 15516, 2, 0, 0),
('fankriss', 'Fankriss'' Wormcaller Greaves', 21365, 79, 60, 'Every step leaves a tunnel.', 15510, 2, 0, 0),
('viscidus', 'Viscidus-Slick Vambraces', 22671, 79, 60, 'Frozen, shattered, and still oozing.', 15299, 2, 0, 0),
('huhuran', 'Huhuran''s Wyvern-Sting Bracers', 22665, 79, 60, 'The princess frenzied at the end. You can too, every two minutes.', 15509, 2, 0, 0),
('veknilash', 'Vek''nilash''s Uppercut Gauntlets', 22670, 79, 60, 'Magic never touched Vek''nilash. Fists did.', 15275, 2, 0, 0),
('veklor', 'Vek''lor''s Arcane Burst Orb', 21597, 79, 60, 'Steel never touched Vek''lor. Spells did.', 15276, 2, 0, 0),
('ouro', 'Ouro''s Sandscour Cowl', 21353, 79, 60, 'Ouro surfaced under you. Now the ground answers to you.', 15517, 2, 0, 0),
('cthun', 'The Eye That Whispers', 22732, 88, 60, '"You will die here," it says, every time you put it on.', 15727, 2, 0, 0),
('anubrekhan', 'Anub''Rekhan''s Locust Carapace', 22419, 86, 60, 'The swarm moved as one. So does the armor.', 15956, 2, 0, 0),
('faerlina', 'Faerlina''s Widow''s Sash', 22502, 86, 60, 'Her worshippers died to calm her. You only need ninety seconds.', 15953, 2, 0, 0),
('maexxna', 'Maexxna''s Silkwrap Girdle', 21586, 86, 60, 'Web wrap, venom, repeat.', 15952, 2, 0, 0),
('noth', 'Noth''s Plaguebringer Rod', 22820, 86, 60, 'Noth spread the plague. This undoes it, one cure at a time.', 15954, 2, 0, 0),
('heigan', 'Heigan''s Dancing Boots', 22440, 86, 60, 'The dance never ends. Make it someone else''s turn.', 15936, 2, 0, 0),
('loatheb', 'Loatheb''s Sporecap Pendant', 19377, 86, 60, 'Loatheb''s spores stopped all healing. The pendant keeps your mana from running dry.', 16011, 2, 0, 0),
('razuvious', 'Razuvious'' Disrupting Training Mace', 23362, 86, 60, 'The instructor taught by example. Lesson one: stop casting.', 16061, 2, 0, 0),
('gothik', 'Gothik''s Deathweave Shroud', 19378, 86, 60, 'Gothik harvested souls on both sides of the gate.', 16060, 2, 0, 0),
('patchwerk', 'Patchwerk''s Stitched Girdle', 23219, 86, 60, 'Patchwerk want to play? Patchwerk wear belt.', 16028, 2, 0, 0),
('grobbulus', 'Grobbulus'' Mutagen Injector', 22802, 86, 60, 'Do not inject. Do not stand near anyone who did.', 15931, 2, 0, 0),
('gluth', 'Gluth''s Gnawed Spaulders', 22479, 86, 60, 'Gluth ate zombies to heal. These are the leftovers.', 15932, 2, 0, 0),
('thaddius', 'Thaddius'' Polarity Coil', 23025, 86, 60, 'Positive or negative, it hits the same.', 15928, 2, 0, 0),
('sapphiron', 'Sapphiron''s Frostwyrm Helm', 22438, 86, 60, 'Ice Block before the breath. Or just wear this.', 15989, 2, 0, 0),
('kelthuzad', 'Phylactery Shard of Kel''Thuzad', 23041, 92, 60, 'Kel''Thuzad kept his soul in a phylactery. One piece fell out.', 15990, 2, 0, 0),
('azuregos', 'Azuregos'' Leyline Cloak', 18208, 75, 60, 'Azuregos guards Azshara''s magic. He would like it back.', 6109, 3, 0, 0),
('kazzak', 'Kazzak''s Doomblade', 19168, 75, 60, 'Kazzak has conquered Azeroth before. He kept a spare blade.', 12397, 3, 0, 0),
('ysondre', 'Ysondre''s Emerald Band', 19138, 75, 60, 'The Dreamer heals what the Nightmare takes.', 14887, 3, 0, 0),
('lethon', 'Lethon''s Shadowdrain Bracers', 20626, 75, 60, 'Lethon draws his shades from your blood. The bracers return the favor.', 14888, 3, 0, 0),
('emeriss', 'Emeriss'' Rotting Girdle', 16936, 75, 60, 'Putrid mushrooms grew from the buckle. They are still growing.', 14889, 3, 0, 0),
('taerar', 'Taerar''s Nightmare Ward', 17106, 75, 60, 'Taerar split into shades. One of them stayed in the shield.', 14890, 3, 0, 0);
